defmodule Arbor.Contracts.Coding.ForgeProjectionVectors do
  @moduledoc """
  Committed test vectors for `Arbor.Contracts.Coding.ForgeProjection` v1.

  `build_input/1` is a complete, valid input. The hex constants below were
  produced once from that input and are frozen: any change to the wire format,
  the canonical JSON, or the canonical signing message changes them and must be
  a deliberate, reviewed version bump.
  """

  @key_id "agent_" <> String.duplicate("0f", 32)
  @commit "d42f57f55efb7b2fa956d5dcbdee4c6f4630b962"
  @ledger_digest "sha256:" <> String.duplicate("ab", 32)

  @body_hex ""
  @body_sha256 "99f09c7e1a40c5925b560f9d7de4675edb6bb2f5ce64842d8bd380ba0edffff0"
  @canonical_hex ""

  @doc "A complete valid build input; `overrides` are merged on top."
  @spec build_input(map()) :: map()
  def build_input(overrides \\ %{}) do
    Map.merge(
      %{
        "task" => "task_coding_42",
        "cycle" => 1,
        "verdict" => "human_review",
        "disposition" => "succeeded",
        "vote_counts" => %{
          "approve" => 7,
          "reject" => 2,
          "abstain" => 1,
          "failed" => 1,
          "reported" => 0
        },
        "tier_reasons" => ["contracts_app", "human_review_required", "security_authority_surface"],
        "finding_counts" => %{"blocking" => 3, "major" => 2, "minor" => 5, "nit" => 1},
        "reviewed_commit" => @commit,
        "candidate" => @commit,
        "ledger_digest" => @ledger_digest,
        "evidence_ref" =>
          "refs/arbor/evidence/6739fbf6bff817e8fdbaf54c06da5c45c1864c65f69eb4585d1e955131915462/a87d2baa",
        "key_id" => @key_id,
        "factory_id" => "factory-test",
        "forge_host" => "git.example",
        "project" => "acme/arbor",
        "poster_agent_id" => @key_id
      },
      overrides
    )
  end

  @doc "The signing context half of `build_input/0`."
  @spec signing_context() :: map()
  def signing_context,
    do: Map.take(build_input(), ["factory_id", "forge_host", "project", "poster_agent_id"])

  @doc "Expected `body_without_footer` bytes for `build_input/0`."
  @spec body() :: binary()
  def body, do: Base.decode16!(@body_hex, case: :lower)

  @doc "Expected lowercase hex SHA-256 of `body/0`."
  @spec body_sha256() :: String.t()
  def body_sha256, do: @body_sha256

  @doc "Expected canonical_v1 signing message for `build_input/0`."
  @spec canonical() :: binary()
  def canonical, do: Base.decode16!(@canonical_hex, case: :lower)

  @doc "The key id used by `build_input/0`."
  @spec key_id() :: String.t()
  def key_id, do: @key_id

  @doc "The commit used by `build_input/0`."
  @spec commit() :: String.t()
  def commit, do: @commit

  @doc "The ledger digest used by `build_input/0`."
